        'Zapytanie jest bezpłatne. Zakres i warunki realizacji projektu ustalamy osobno.' => 'Your inquiry is free. We agree the project scope and delivery terms separately.',
        'Spis treści' => 'Contents',
        'W tym dokumencie' => 'In this document',
        '<1>01</1>Usługodawca i zakres dokumentu' => '<1>01</1>Service provider and scope of this document',
        '<1>02</1>Konsument i przedsiębiorca na prawach konsumenta' => '<1>02</1>Consumers and sole traders with consumer rights',
        '<1>03</1>Bezpłatne formularze i Studio Wyceny' => '<1>03</1>Free forms and the Quote Studio',
